def apply_patch(original: str, diff: str) -> str:
    original = original.replace('\r\n', '\n')
    diff = diff.replace('\r\n', '\n')

    if not original:
        orig_lines = []
    else:
        orig_lines = original.splitlines(True)

    diff_lines = diff.splitlines(True)

    hunk_start = -1
    for i, line in enumerate(diff_lines):
        if line.startswith('@@'):
            hunk_start = i
            break

    if hunk_start == -1:
        return original

    result = []
    old_idx = 0
    i = hunk_start

    while i < len(diff_lines):
        line = diff_lines[i]
        if line.startswith('@@'):
            parts = line.split()
            old_part = parts[1][1:]
            new_part = parts[2][1:]

            if ',' in old_part:
                old_start, old_count = map(int, old_part.split(','))
            else:
                old_start, old_count = int(old_part), 1

            if ',' in new_part:
                new_start, new_count = map(int, new_part.split(','))
            else:
                new_start, new_count = int(new_part), 1

            i += 1
            body = []
            while i < len(diff_lines) and not diff_lines[i].startswith('@@'):
                body.append(diff_lines[i])
                i += 1

            old_cnt = sum(1 for b in body if b.startswith(' ') or b.startswith('-'))
            new_cnt = sum(1 for b in body if b.startswith(' ') or b.startswith('+'))

            if old_cnt != old_count:
                raise ValueError(f"Old count mismatch: expected {old_count}, got {old_cnt}")
            if new_cnt != new_count:
                raise ValueError(f"New count mismatch: expected {new_count}, got {new_cnt}")

            if old_count == 0:
                expected_idx = old_start
            else:
                expected_idx = old_start - 1

            if expected_idx != old_idx:
                raise ValueError(f"Position mismatch: expected {expected_idx}, got {old_idx}")

            last_processed_line_idx = len(result) - 1

            for j, bl in enumerate(body):
                if bl.strip() == '\\ No newline at end of file':
                    if last_processed_line_idx >= 0:
                        last_line = result[last_processed_line_idx]
                        if last_line.endswith('\n'):
                            result[last_processed_line_idx] = last_line[:-1]
                    continue

                if bl.startswith(' '):
                    if old_idx >= len(orig_lines):
                        raise ValueError("Context line out of bounds")
                    orig_line = orig_lines[old_idx]
                    if bl[1:] != orig_line:
                        raise ValueError("Context mismatch")
                    result.append(orig_line)
                    last_processed_line_idx = len(result) - 1
                    old_idx += 1
                elif bl.startswith('-'):
                    if old_idx >= len(orig_lines):
                        raise ValueError("Removed line out of bounds")
                    orig_line = orig_lines[old_idx]
                    if bl[1:] != orig_line:
                        raise ValueError("Removed mismatch")
                    last_processed_line_idx = len(result) - 1
                    old_idx += 1
                elif bl.startswith('+'):
                    result.append(bl[1:])
                    last_processed_line_idx = len(result) - 1
                else:
                    raise ValueError(f"Invalid hunk line: {bl}")

            if old_idx != expected_idx + old_count:
                raise ValueError("Hunk consumption mismatch")

    if old_idx < len(orig_lines):
        result.extend(orig_lines[old_idx:])

    return ''.join(result)
