from typing import List, Callable, Any

async def gather_limited(factories: List[Callable], limit: int, timeout: float | None = None) -> List[Any]:
    if limit < 1:
        raise ValueError("limit must be >= 1")
    if not factories:
        return []

    results = [None] * len(factories)
    semaphore = asyncio.Semaphore(limit)
    first_exception = None
    first_exception_event = asyncio.Event()

    async def worker(index: int, factory: Callable):
        nonlocal first_exception
        try:
            async with semaphore:
                coro = factory()
                if timeout is not None:
                    result = await asyncio.wait_for(coro, timeout=timeout)
                else:
                    result = await coro
                results[index] = result
        except asyncio.CancelledError:
            raise
        except Exception as e:
            if first_exception is None:
                first_exception = e
                first_exception_event.set()
            raise

    tasks = [asyncio.create_task(worker(i, f)) for i, f in enumerate(factories)]

    try:
        done, pending = await asyncio.wait(tasks, return_when=asyncio.FIRST_EXCEPTION)
    except asyncio.CancelledError:
        for t in tasks:
            if not t.done():
                t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise

    if first_exception is not None:
        for t in tasks:
            if not t.done():
                t.cancel()
        await asyncio.gather(*tasks, return_exceptions=True)
        raise first_exception

    return results
