import re

class Node:
    pass

class NumNode(Node):
    def __init__(self, val):
        self.val = val
    def eval(self, env):
        return self.val

class VarNode(Node):
    def __init__(self, name):
        self.name = name
    def eval(self, env):
        if self.name not in env:
            raise NameError(f"Unknown variable '{self.name}'")
        return env[self.name]

class BinOpNode(Node):
    def __init__(self, op, left, right):
        self.op = op
        self.left = left
        self.right = right
    def eval(self, env):
        l = self.left.eval(env)
        r = self.right.eval(env)
        if self.op == '+':
            return l + r
        if self.op == '-':
            return l - r
        if self.op == '*':
            return l * r
        if self.op == '/':
            if r == 0:
                raise ZeroDivisionError
            if isinstance(l, int) and isinstance(r, int) and l % r == 0:
                return l // r
            return l / r
        if self.op == '%':
            if r == 0:
                raise ZeroDivisionError
            return l % r
        if self.op == '^':
            return l ** r
        if self.op == '||':
            return 1 if l or r else 0
        if self.op == '&&':
            return 1 if l and r else 0
        if self.op == '==':
            return 1 if l == r else 0
        if self.op == '!=':
            return 1 if l != r else 0
        if self.op == '<':
            return 1 if l < r else 0
        if self.op == '<=':
            return 1 if l <= r else 0
        if self.op == '>':
            return 1 if l > r else 0
        if self.op == '>=':
            return 1 if l >= r else 0
        raise SyntaxError(f"Unknown operator '{self.op}'")

class UnaryOpNode(Node):
    def __init__(self, op, operand):
        self.op = op
        self.operand = operand
    def eval(self, env):
        v = self.operand.eval(env)
        if self.op == '-':
            return -v
        if self.op == '+':
            return +v
        if self.op == '!':
            return 1 if v == 0 else 0
        raise SyntaxError(f"Unknown unary operator '{self.op}'")

class CondNode(Node):
    def __init__(self, test, true_expr, false_expr):
        self.test = test
        self.true_expr = true_expr
        self.false_expr = false_expr
    def eval(self, env):
        if self.test.eval(env):
            return self.true_expr.eval(env)
        else:
            return self.false_expr.eval(env)

class CallNode(Node):
    def __init__(self, func, args):
        self.func = func
        self.args = args
    def eval(self, env):
        if self.func == 'min':
            if not self.args:
                raise SyntaxError("min() requires at least one argument")
            return min(a.eval(env) for a in self.args)
        if self.func == 'max':
            if not self.args:
                raise SyntaxError("max() requires at least one argument")
            return max(a.eval(env) for a in self.args)
        if self.func == 'abs':
            if len(self.args) != 1:
                raise SyntaxError("abs() requires exactly one argument")
            return abs(self.args[0].eval(env))
        raise NameError(f"Unknown function '{self.func}'")

def tokenize(expr: str):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        if expr[i].isspace():
            i += 1
            continue

        # Numbers
        m = re.match(r'\d+\.?\d*|\.\d+', expr[i:])
        if m:
            num_str = m.group(0)
            if '.' in num_str:
                tokens.append(('NUMBER', float(num_str)))
            else:
                tokens.append(('NUMBER', int(num_str)))
            i += len(num_str)
            continue

        # Identifiers
        m = re.match(r'[A-Za-z_][A-Za-z0-9_]*', expr[i:])
        if m:
            tokens.append(('IDENT', m.group(0)))
            i += len(m.group(0))
            continue

        # Operators
        if expr[i:i+2] in ('||', '&&', '==', '!=', '<=', '>='):
            tokens.append(('OP', expr[i:i+2]))
            i += 2
            continue
        if expr[i] in '?':
            tokens.append(('OP', '?'))
            i += 1
            continue
        if expr[i] in ':':
            tokens.append(('OP', ':'))
            i += 1
            continue
        if expr[i] in '+-*/%^!()':
            tokens.append(('OP', expr[i]))
            i += 1
            continue

        # Errors
        if expr[i] in '&|=':
            raise SyntaxError(f"Unexpected character '{expr[i]}'")
        raise SyntaxError(f"Unexpected character '{expr[i]}'")

    tokens.append(('EOF', None))
    return tokens

class Parser:
    def __init__(self, tokens, env):
        self.tokens = tokens
        self.env = env or {}
        self.pos = 0

    def current(self):
        return self.tokens[self.pos]

    def consume(self, expected_type=None, expected_val=None):
        tok = self.current()
        if expected_type and tok[0] != expected_type:
            raise SyntaxError(f"Expected {expected_type}, got {tok[0]}")
        if expected_val and tok[1] != expected_val:
            raise SyntaxError(f"Expected {expected_val}, got {tok[1]}")
        self.pos += 1
        return tok

    def expect(self, t_type, t_val=None):
        return self.consume(t_type, t_val)

    def parse(self):
        res = self.parse_conditional()
        if self.current()[0] != 'EOF':
            raise SyntaxError(f"Unexpected token {self.current()}")
        return res

    def parse_conditional(self):
        left = self.parse_or()
        if self.current()[1] == '?':
            self.consume('OP', '?')
            right_true = self.parse_conditional()
            self.expect('OP', ':')
            right_false = self.parse_conditional()
            return CondNode(left, right_true, right_false)
        return left

    def parse_or(self):
        left = self.parse_and()
        while self.current()[1] == '||':
            self.consume('OP', '||')
            right = self.parse_and()
            left = BinOpNode('||', left, right)
        return left

    def parse_and(self):
        left = self.parse_compare()
        while self.current()[1] == '&&':
            self.consume('OP', '&&')
            right = self.parse_compare()
            left = BinOpNode('&&', left, right)
        return left

    def parse_compare(self):
        left = self.parse_add()
        if self.current()[1] in ('==', '!=', '<', '<=', '>', '>='):
            op = self.consume('OP')[1]
            right = self.parse_add()
            return BinOpNode(op, left, right)
        return left

    def parse_add(self):
        left = self.parse_mul()
        while self.current()[1] in ('+', '-'):
            op = self.consume('OP')[1]
            right = self.parse_mul()
            left = BinOpNode(op, left, right)
        return left

    def parse_mul(self):
        left = self.parse_unary()
        while self.current()[1] in ('*', '/', '%'):
            op = self.consume('OP')[1]
            right = self.parse_unary()
            left = BinOpNode(op, left, right)
        return left

    def parse_unary(self):
        if self.current()[1] in ('-', '+', '!'):
            op = self.consume('OP')[1]
            operand = self.parse_unary()
            return UnaryOpNode(op, operand)
        return self.parse_power()

    def parse_power(self):
        base = self.parse_atom()
        if self.current()[1] == '^':
            self.consume('OP', '^')
            exponent = self.parse_power()
            return BinOpNode('^', base, exponent)
        return base

    def parse_atom(self):
        tok = self.current()
        if tok[0] == 'NUMBER':
            self.consume()
            return NumNode(tok[1])
        if tok[0] == 'IDENT':
            name = self.consume()[1]
            if self.current()[1] == '(':
                self.consume('OP', '(')
                args = []
                if self.current()[1] != ')':
                    args.append(self.parse_conditional())
                    while self.current()[1] == ',':
                        self.consume('OP', ',')
                        args.append(self.parse_conditional())
                self.expect('OP', ')')
                return CallNode(name, args)
            else:
                return VarNode(name)
        if tok[1] == '(':
            self.consume('OP', '(')
            res = self.parse_conditional()
            self.expect('OP', ')')
            return res
        raise SyntaxError(f"Unexpected token {tok}")

def evaluate(expr: str, env: dict[str, float] | None = None) -> int | float:
    if not expr.strip():
        raise SyntaxError("Empty input")
    tokens = tokenize(expr)
    parser = Parser(tokens, env)
    ast = parser.parse()
    return ast.eval(env or {})
