import heapq

def route(grid):
    # Validation
    if not grid or not all(len(row) == len(grid[0]) for row in grid):
        raise ValueError("Ragged rows")
    rows, cols = len(grid), len(grid[0])
    s_pos = None
    e_pos = None
    letter_counts = {}
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch == 'S':
                if s_pos is not None: raise ValueError("Multiple S")
                s_pos = (r, c)
            elif ch == 'E':
                if e_pos is not None: raise ValueError("Multiple E")
                e_pos = (r, c)
            elif ch == '#':
                pass
            elif ch == '.':
                pass
            elif ch in '123456789':
                pass
            elif ch.islower():
                letter_counts[ch] = letter_counts.get(ch, 0) + 1
            else:
                raise ValueError("Unknown character")
    if s_pos is None or e_pos is None:
        raise ValueError("Missing S or E")
    for ch, cnt in letter_counts.items():
        if cnt != 2:
            raise ValueError(f"Letter {ch} appears {cnt} times")

    # Precompute pads
    pads = {}
    for r in range(rows):
        for c in range(cols):
            ch = grid[r][c]
            if ch.islower():
                pads.setdefault(ch, []).append((r, c))

    # Cost function
    def cell_cost(ch):
        if ch in 'SE.#' or ch.islower():
            return 1
        return int(ch)

    # Directions: D, L, R, U
    dirs = [('D', 1, 0), ('L', 0, -1), ('R', 0, 1), ('U', -1, 0)]

    # Dijkstra
    dist = [[(float('inf'), "") for _ in range(cols)] for _ in range(rows)]
    sr, sc = s_pos
    dist[sr][sc] = (0, "")
    pq = [(0, "", sr, sc)]
    visited = set()

    er, ec = e_pos

    while pq:
        cost, moves, r, c = heapq.heappop(pq)

        if (r, c) in visited:
            continue
        visited.add((r, c))

        if (r, c) == (er, ec):
            return (cost, moves)

        # Try moves in order D, L, R, U
        for m, dr, dc in dirs:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                ch = grid[nr][nc]
                if ch == '#':
                    continue
                w = cell_cost(ch)
                new_cost = cost + w
                new_moves = moves + m
                if (new_cost, new_moves) < dist[nr][nc]:
                    dist[nr][nc] = (new_cost, new_moves)
                    heapq.heappush(pq, (new_cost, new_moves, nr, nc))

        # T move
        if grid[r][c].islower():
            letter = grid[r][c]
            other_r, other_c = pads[letter][0] if (r, c) == pads[letter][1] else pads[letter][1]
            new_cost = cost + 2
            new_moves = moves + 'T'
            if (new_cost, new_moves) < dist[other_r][other_c]:
                dist[other_r][other_c] = (new_cost, new_moves)
                heapq.heappush(pq, (new_cost, new_moves, other_r, other_c))

    return None
