def load_ini(text: str) -> dict[str, dict[str, str]]:
    lines = text.split('\n')
    sections = {}
    current_section = ""
    current_key = None
    current_value = None
    in_continuation = False

    def parse_value(val_str: str, line_num: int) -> str:
        res = []
        in_quote = False
        i = 0
        n = len(val_str)
        while i < n:
            c = val_str[i]
            if in_quote:
                if c == '\\' and i + 1 < n and val_str[i+1] == '"':
                    res.append('"')
                    i += 2
                    continue
                elif c == '"':
                    in_quote = False
                else:
                    res.append(c)
            else:
                if c == '"':
                    in_quote = True
                elif c in (' ', '\t') and i + 1 < n and val_str[i+1] in ('#', ';'):
                    break
                else:
                    res.append(c)
            i += 1
        if in_quote:
            raise ValueError(f"unterminated quote at line {line_num}")
        return ''.join(res)

    for line_num_0, line in enumerate(lines):
        line_num = line_num_0 + 1
        line = line.rstrip('\r')

        if line.strip() == '':
            in_continuation = False
            continue

        if line.lstrip().startswith('#') or line.lstrip().startswith(';'):
            in_continuation = False
            continue

        if line.lstrip().startswith('['):
            idx = line.find(']')
            if idx == -1:
                raise ValueError(f"unclosed [ at line {line_num}")
            section_name = line[1:idx].strip()
            if section_name not in sections:
                sections[section_name] = {}
            current_section = section_name
            current_key = None
            in_continuation = False
            continue

        if line[0] in (' ', '\t') and current_key is not None:
            if not in_continuation:
                in_continuation = True
            current_value += '\n' + line.strip()
            sections[current_section][current_key] = current_value
            continue

        if line[0] in (' ', '\t') and current_key is None:
            raise ValueError(f"continuation line with no preceding entry at line {line_num}")

        eq_idx = line.find('=')
        colon_idx = line.find(':')
        sep_idx = -1
        if eq_idx != -1 and colon_idx != -1:
            sep_idx = min(eq_idx, colon_idx)
        elif eq_idx != -1:
            sep_idx = eq_idx
        elif colon_idx != -1:
            sep_idx = colon_idx
        else:
            raise ValueError(f"missing separator at line {line_num}")

        key_part = line[:sep_idx].strip().lower()
        val_part = line[sep_idx+1:].strip()

        current_value = parse_value(val_part, line_num)
        current_key = key_part
        in_continuation = False

        if current_section not in sections:
            sections[current_section] = {}
        sections[current_section][current_key] = current_value

    if "" in sections and not sections[""]:
        del sections[""]

    resolving = set()
    cache = {}

    def resolve_key(sec: str, key: str) -> str:
        if (sec, key) in cache:
            return cache[(sec, key)]
        if (sec, key) in resolving:
            raise ValueError(f"reference cycle detected involving {sec}:{key}")

        resolving.add((sec, key))
        val = sections[sec][key]
        resolved_val = resolve_value(sec, val)
        cache[(sec, key)] = resolved_val
        resolving.discard((sec, key))
        return resolved_val

    def resolve_value(sec: str, value: str) -> str:
        res = []
        i = 0
        n = len(value)
        while i < n:
            if value[i] == '$':
                if i + 1 < n and value[i+1] == '$':
                    res.append('$')
                    i += 2
                elif i + 1 < n and value[i+1] == '{':
                    j = value.find('}', i+2)
                    if j == -1:
                        res.append(value[i])
                        i += 1
                    else:
                        ref = value[i+2:j]
                        if ':' in ref:
                            ref_sec, ref_key = ref.split(':', 1)
                        else:
                            ref_sec = sec
                            ref_key = ref
                        ref_key = ref_key.lower()

                        if ref_sec not in sections or ref_key not in sections[ref_sec]:
                            raise ValueError(f"undefined reference: {ref}")

                        if (ref_sec, ref_key) in resolving:
                            raise ValueError(f"reference cycle detected involving {ref}")

                        resolved_ref = resolve_key(ref_sec, ref_key)
                        res.append(resolved_ref)
                        i = j + 1
                else:
                    res.append('$')
                    i += 1
            else:
                res.append(value[i])
                i += 1
        return ''.join(res)

    for sec in sections:
        for key in sections[sec]:
            resolve_key(sec, key)

    for sec in sections:
        for key in sections[sec]:
            sections[sec][key] = cache[(sec, key)]

    return sections
