from typing import List, Tuple, Optional

class Version:
    def __init__(self, major: int, minor: int, patch: int, prerelease: Optional[List] = None, build: Optional[str] = None):
        self.major = major
        self.minor = minor
        self.patch = patch
        self.prerelease = prerelease or []
        self.build = build or ""

    @classmethod
    def parse(cls, v: str) -> 'Version':
        v = v.strip()
        if v.startswith(('v', '=')):
            v = v[1:]

        build = None
        if '+' in v:
            v, build = v.split('+', 1)
            if not build or not re.match(r'^[0-9A-Za-z-]+(?:\.[0-9A-Za-z-]+)*$', build):
                raise ValueError(f"Invalid build metadata: {build}")

        prerelease = []
        if '-' in v:
            v, pre_str = v.split('-', 1)
            if not pre_str:
                raise ValueError("Empty prerelease")
            for ident in pre_str.split('.'):
                if not ident:
                    raise ValueError("Empty prerelease identifier")
